#[derive(Debug)]
enum ParseError {
    Empty,
    TooLarge(u64),
}

fn bounded_parse(raw: &str) -> Result<u64, ParseError> {
    if raw.is_empty() {
        return Err(ParseError::Empty);
    }
    let value = raw.parse::<u64>().map_err(|_| ParseError::Empty)?;
    if value > 1000 {
        return Err(ParseError::TooLarge(value));
    }
    Ok(value)
}

fn main() {
    for raw in ["", "42", "9999"] {
        println!("{raw:?} → {:?}", bounded_parse(raw));
    }
}

